// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests seller contact parsing on real-site-shaped blocks
// Flo: small HTML > carzPars > assert contact fields
// I/O: html strings > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const pars = @import("pa-carz-pars.zig");
fn arenNewz() std.heap.ArenaAllocator { return std.heap.ArenaAllocator.init(std.testing.allocator); }
test "carpla: shop name above Xem cua hang, address above the posted line, footer contacts ignored" { var aren = arenNewz(); defer aren.deinit(); const html = "<title>Ford Ranger 2023 - 60,000km</title><div>39 Chế Lan Viên, Tây Thạnh, Tân Phú, Hồ Chí Minh</div><div>Đăng 5 tháng trước</div><div>Nhiên liệu</div><div>Dầu</div><div>BẾN THÀNH FORD</div><div>Hồ Chí Minh</div><div>Xem cửa hàng</div><div>Điện thoại: 0853603616; Email: carpla.media@carpla.vn</div>"; const carz = try pars.carzPars(aren.allocator(), "https://carpla.vn/xe/ford-ranger-2023-f8xz1", html, 2026); try std.testing.expectEqualStrings("BẾN THÀNH FORD", carz.cnam); try std.testing.expectEqualStrings("39 Chế Lan Viên, Tây Thạnh, Tân Phú, Hồ Chí Minh", carz.cadd); try std.testing.expectEqualStrings("dealer", carz.sell); try std.testing.expectEqualStrings("", carz.cmai); try std.testing.expectEqualStrings("", carz.phon); }
test "oto.com.vn: name and phone follow Tin cung nguoi ban; cards of other sellers above are not read" { var aren = arenNewz(); defer aren.deinit(); const html = "<title>Mua bán Porsche Panamera 2020 giá 3 tỉ 250 triệu - 1</title><div>Good Car</div><div>0923 456 234</div><div>Tin cùng người bán</div><div>AUTO CHỐT</div><div>0907 140 000</div><div>2019 - Lexus LX 570</div>"; const carz = try pars.carzPars(aren.allocator(), "https://oto.com.vn/mua-ban-xe-x/y-aid123", html, 2026); try std.testing.expectEqualStrings("AUTO CHỐT", carz.cnam); try std.testing.expectEqualStrings("0907 140 000", carz.phon); try std.testing.expectEqualStrings("dealer", carz.sell); try std.testing.expectEqualStrings("AUTO CHỐT", carz.shop); }
test "tinbanxe: name above the address label, address inline, description stops before them" { var aren = arenNewz(); defer aren.deinit(); const html = "<title>Audi Q8 2022</title><div>Mô tả</div><div>Bán Audi Q8 lướt</div><div>Daehan Motors</div><div>Địa chỉ: Phòng 2101, Tầng 21, Pearl Plaza, Bình Thạnh</div><div>Gọi ngay Zalo</div><div>Xe cùng phân khúc</div><div>Hoang Tram</div><div>Địa chỉ: 4 duong 182, Thủ Đức</div>"; const carz = try pars.carzPars(aren.allocator(), "https://tinbanxe.vn/audi-q8-2022-trang-89570/", html, 2026); try std.testing.expectEqualStrings("Daehan Motors", carz.cnam); try std.testing.expectEqualStrings("Phòng 2101, Tầng 21, Pearl Plaza, Bình Thạnh", carz.cadd); try std.testing.expectEqualStrings("dealer", carz.sell); try std.testing.expectEqualStrings("Bán Audi Q8 lướt", carz.text); }
test "bonbanh and carmudi: private seller keeps the name for the contact book, address inline" { var aren = arenNewz(); defer aren.deinit(); const bonb = try pars.carzPars(aren.allocator(), "https://bonbanh.com/xe-toyota-land_cruiser-2026-6986108", "<title>Toyota Land Cruiser 2026</title><div>Liên hệ người bán</div><div>Lê Văn Thuỳ</div><div>Điện thoại:</div><div>0922 079 ***</div><div>Địa chỉ: 368 Võ Chí Công - Tây Hồ - Hà Nội</div>", 2026); try std.testing.expectEqualStrings("Lê Văn Thuỳ", bonb.cnam); try std.testing.expectEqualStrings("private", bonb.sell); try std.testing.expectEqualStrings("368 Võ Chí Công - Tây Hồ - Hà Nội", bonb.cadd); try std.testing.expectEqualStrings("0922 079 ***", bonb.phon); const carm = try pars.carzPars(aren.allocator(), "https://carmudi.vn/ban-xe-oto-bmw-x3-543842/", "<title>BMW X3 2020</title><div>Đăng bởi</div><div>Trung Sơn</div><div>Mô tả</div><div>Đổi chủ BMW X3. Zalo 0966.353.678 hoặc 0912 345 678, mail lienhe.bmw@gmail.com</div>", 2026); try std.testing.expectEqualStrings("Trung Sơn", carm.cnam); try std.testing.expectEqualStrings("0966353678", carm.phon); try std.testing.expectEqualStrings("0912345678", carm.cph2); try std.testing.expectEqualStrings("lienhe.bmw@gmail.com", carm.cmai); try std.testing.expect(std.mem.indexOf(u8, carm.cdes, "0966") == null); try std.testing.expect(carm.cdes.len > 10); }
test "chotot: hidden phone stays empty, address follows Chat; email on the site's own domain is skipped; long description is cut at a word" { var aren = arenNewz(); defer aren.deinit(); var lonb: std.ArrayList(u8) = .empty; try lonb.appendSlice(aren.allocator(), "Bán xe Fortuner "); for (0..30) |_| try lonb.appendSlice(aren.allocator(), "rất đẹp "); try lonb.appendSlice(aren.allocator(), "end hotro@chotot.com"); const html = try std.fmt.allocPrint(aren.allocator(), "<title>Toyota Fortuner 2017</title><div>Người bán đã ẩn số điện thoại</div><div>Chat</div><div>Xã Trừ Văn Thố, Huyện Bàu Bàng, Bình Dương</div><div>Mô tả chi tiết</div><div>{s}</div>", .{lonb.items}); const carz = try pars.carzPars(aren.allocator(), "https://xe.chotot.com/mua-ban-oto-binh-duong/134891221.htm", html, 2026); try std.testing.expectEqualStrings("", carz.phon); try std.testing.expectEqualStrings("Xã Trừ Văn Thố, Huyện Bàu Bàng, Bình Dương", carz.cadd); try std.testing.expectEqualStrings("", carz.cmai); try std.testing.expect(carz.cdes.len <= 160 and carz.cdes.len > 100); try std.testing.expectEqualStrings("", carz.cnam); }
